#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [EntityBehaviourDefinition(VanillaContraptionNames.miniSkyward)]
    public class MiniSkyward : DispenserFamily
    {
        public MiniSkyward(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            InitShootTimer(entity);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            UpdatePosition(entity);
            ShootTick(entity);
        }
        public override Entity? Shoot(Entity entity)
        {
            var param = entity.GetShootParams();

            var magnitude = STAR_VELOCITY.magnitude;
            var range = entity.GetRange();
            var endRangePoint = (entity.Position.x + range) * entity.GetFacingX();
            Vector3 endPoint = new Vector3 (endRangePoint, entity.GetGroundY(), entity.Position.z);
            var angle = (endPoint - entity.Position).normalized;
            param.velocity = angle * magnitude;

            return entity.ShootProjectile(param);
        }
        public override bool CanEvoke(Entity entity)
        {
            return false;
        }
        protected override int GetTimerTime(Entity entity)
        {
            return FIRE_INTERVAL;
        }
        public void UpdatePosition(Entity entity)
        {
            var parent = entity.Parent;
            if (!parent.ExistsAndAlive())
                return;
            if (!parent.IsEntityOf(VanillaContraptionID.skywardBeacon))
                return;
            var targetPosition = SkywardBeacon.GetStrikePosition(parent) - entity.GetFacingDirection() * entity.Level.GetGridWidth() + Vector3.up * entity.Level.GetGridHeight();
            var pos = entity.Position;
            pos.x = pos.x * 0.5f + targetPosition.x * 0.5f;
            pos.y = pos.y * 0.5f + targetPosition.y * 0.5f;
            pos.z = pos.z * 0.5f + targetPosition.z * 0.5f;
            entity.Position = pos;
        }
        public const int FIRE_INTERVAL = 60;
        public static readonly Vector3 STAR_VELOCITY = new Vector3(20, -20, 0);
    }
}
